INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'heritage', 'n.', '/ˈherɪtɪdʒ/', '遗产;传统', 'Few visitors are surprised that the island is a World Heritage site full of natural heritage.', '很少有游客会惊讶这座岛是充满自然遗产的世界遗产地。', 'A Delicate World', 1, 0, 'senior', 'wordlist', 'elective2', 'U5', 'World Heritage Site', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'habitat', 'n.', '/ˈhæbɪtæt/', '栖息地', 'The birds lived in perfect harmony with their natural habitat for thousands of years.', '这些鸟与它们的自然栖息地和谐相处了数千年。', 'A Delicate World', 2, 0, 'senior', 'wordlist', 'elective2', 'U5', 'natural habitat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'inhabitant', 'n.', '/ɪnˈhæbɪtənt/', '栖居的动物;居民', 'Penguins and seals were the native inhabitants of the lonely island.', '企鹅和海豹是这座孤岛上的本地栖居动物。', 'A Delicate World', 3, 0, 'senior', 'wordlist', 'elective2', 'U5', 'native inhabitant', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'penguin', 'n.', '/ˈpeŋɡwɪn/', '企鹅', 'Thousands of royal penguins gather on the rocky shore each year.', '每年都有成千上万只皇企鹅聚集在岩石海岸上。', 'A Delicate World', 4, 0, 'senior', 'wordlist', 'elective2', 'U5', 'royal penguin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'appetite', 'n.', '/ˈæpətaɪt/', '胃口,食欲', 'Unluckily, the cats soon developed an appetite for the native birds too.', '不幸的是,猫很快也对本地鸟类产生了食欲。', 'A Delicate World', 5, 0, 'senior', 'wordlist', 'elective2', 'U5', 'develop an appetite for', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'multiply', 'v.', '/ˈmʌltɪplaɪ/', '(使)大大增加,(使)倍增', 'Set loose on the island, the rabbits multiplied rapidly and ate the plants.', '兔子在岛上放养后大量繁殖,吃光了植物。', 'A Delicate World', 6, 0, 'senior', 'wordlist', 'elective2', 'U5', 'multiply rapidly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'vegetation', 'n.', '/ˌvedʒɪˈteɪʃ(ə)n/', '植物,草木(总称)', 'The hungry rabbits destroyed much of the native vegetation.', '饥饿的兔子毁掉了大量本地草木。', 'A Delicate World', 7, 0, 'senior', 'wordlist', 'elective2', 'U5', 'native vegetation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'erosion', 'n.', '/ɪˈrəʊʒ(ə)n/', '侵蚀', 'Digging holes everywhere, the rabbits caused serious soil erosion.', '兔子到处挖洞,造成了严重的水土侵蚀。', 'A Delicate World', 8, 0, 'senior', 'wordlist', 'elective2', 'U5', 'soil erosion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'subsequently', 'adv.', '/ˈsʌbsɪkwəntli/', '后来,随后', 'The cats subsequently turned their attention back to the seabirds.', '猫随后又把注意力转回到了海鸟身上。', 'A Delicate World', 9, 0, 'senior', 'wordlist', 'elective2', 'U5', 'subsequently develop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dramatically', 'adv.', '/drəˈmætɪkli/', '显著地,剧烈地', 'The green grass and bare rock contrast dramatically across the landscape.', '绿草与裸岩在这片地貌上形成鲜明对比。', 'A Delicate World', 10, 0, 'senior', 'wordlist', 'elective2', 'U5', 'change dramatically', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'chaos', 'n.', '/ˈkeɪɒs/', '大混乱;紊乱', 'A single careless act threw the whole island into chaos.', '一个不慎之举就把整座岛抛入了混乱。', 'A Delicate World', 11, 0, 'senior', 'wordlist', 'elective2', 'U5', 'from chaos to order', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conservation', 'n.', '/ˌkɒnsəˈveɪʃ(ə)n/', '保护', 'The long story moved at last from chaos to conservation.', '这个漫长的故事最终从混乱走向了保护。', 'A Delicate World', 12, 0, 'senior', 'wordlist', 'elective2', 'U5', 'nature conservation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'virus', 'n.', '/ˈvaɪərəs/', '病毒', 'Experts released a virus to bring the rabbit numbers down.', '专家们释放了一种病毒以降低兔子的数量。', 'A Delicate World', 13, 0, 'senior', 'wordlist', 'elective2', 'U5', 'release a virus', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'decrease', 'v.', '/dɪˈkriːs/', '(使)减少,(使)变小', 'The virus caused the rabbit population to decrease for a while.', '这种病毒一度使兔子数量减少。', 'A Delicate World', 14, 0, 'senior', 'wordlist', 'elective2', 'U5', 'decrease sharply', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'trap', 'n.', '/træp/', '夹子,陷阱', 'In the 1980s, traps and dogs were used to catch the wild cats.', '在20世纪80年代,人们用陷阱和狗来捕捉野猫。', 'A Delicate World', 15, 0, 'senior', 'wordlist', 'elective2', 'U5', 'set traps', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'departure', 'n.', '/dɪˈpɑːtʃə/', '离开', 'With the departure of the cats, the mice began to increase again.', '猫离开后,老鼠又开始增多。', 'A Delicate World', 16, 0, 'senior', 'wordlist', 'elective2', 'U5', 'the departure of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'immunity', 'n.', '/ɪˈmjuːnɪti/', '免疫力', 'The surviving rabbits had developed an immunity to the virus.', '幸存的兔子已经对这种病毒产生了免疫力。', 'A Delicate World', 17, 0, 'senior', 'wordlist', 'elective2', 'U5', 'develop immunity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'explode', 'v.', '/ɪkˈspləʊd/', '(数量)突然增加;爆炸', 'Free of enemies, the rabbit numbers exploded once again.', '没有天敌后,兔子的数量再次激增。', 'A Delicate World', 18, 0, 'senior', 'wordlist', 'elective2', 'U5', 'explode in number', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'collapse', 'v.', '/kəˈlæps/', '倒坍;塌下', 'The rabbits'' digging made some land collapse, killing many penguins.', '兔子挖洞使一些土地塌陷,害死了许多企鹅。', 'A Delicate World', 19, 0, 'senior', 'wordlist', 'elective2', 'U5', 'collapse suddenly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'substantial', 'adj.', '/səbˈstænʃ(ə)l/', '大量的,多的', 'A substantial number of penguins were lost in that one incident.', '仅那一次事件就损失了大量企鹅。', 'A Delicate World', 20, 0, 'senior', 'wordlist', 'elective2', 'U5', 'a substantial number', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'incident', 'n.', '/ˈɪnsɪd(ə)nt/', '事件', 'This incident made it clear that the rabbit problem needed solving.', '这一事件清楚地表明,兔子问题必须解决。', 'A Delicate World', 21, 0, 'senior', 'wordlist', 'elective2', 'U5', 'a sad incident', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'intervention', 'n.', '/ˌɪntəˈvenʃ(ə)n/', '干预,介入', 'This intervention was a long, much-delayed ending to a sad story.', '这次干预为一个悲伤的故事画上了迟来已久的句号。', 'A Delicate World', 22, 0, 'senior', 'wordlist', 'elective2', 'U5', 'human intervention', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'owe', 'v.', '/əʊ/', '应该做;对……负有义务;欠', 'We humans owe it to the island to give it a happy ending.', '我们人类有责任给这座岛一个圆满的结局。', 'A Delicate World', 23, 0, 'senior', 'wordlist', 'elective2', 'U5', 'owe it to sb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pest', 'n.', '/pest/', '有害小动物;害虫', 'In 2014 the island was finally declared pest-free.', '2014年,这座岛终于被宣布无害兽。', 'A Delicate World', 24, 0, 'senior', 'wordlist', 'elective2', 'U5', 'pest-free', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ecology', 'n.', '/ɪˈkɒlədʒi/', '生态;生态学', 'The island''s ecology is finally on the road to recovery.', '这座岛的生态终于走上了恢复之路。', 'A Delicate World', 25, 0, 'senior', 'wordlist', 'elective2', 'U5', 'fragile ecology', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'nutrient', 'n.', '/ˈnjuːtriənt/', '养分,营养物', 'Producers absorb water and dissolved nutrients from the soil.', '生产者从土壤中吸收水分和溶解的养分。', 'A Delicate World', 26, 0, 'senior', 'wordlist', 'elective2', 'U5', 'dissolved nutrients', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dissolve', 'v.', '/dɪˈzɒlv/', '(使)溶解', 'The chemicals dissolve in water and return to the food chain.', '这些化学物质溶解在水中,重新回到食物链。', 'A Delicate World', 27, 0, 'senior', 'wordlist', 'elective2', 'U5', 'dissolve in water', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'biological', 'adj.', '/ˌbaɪəˈlɒdʒɪk(ə)l/', '生物的,与生物有关的', 'Scientists can observe biological processes as the species develop.', '科学家可以观察物种发展过程中的生物学过程。', 'A Delicate World', 28, 0, 'senior', 'wordlist', 'elective2', 'U5', 'biological processes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'criterion', 'n.', '/kraɪˈtɪəriən/', '标准,准则', 'Shennongjia meets two important criteria for the Heritage List.', '神农架满足列入遗产名录的两条重要标准。', 'A Delicate World', 29, 0, 'senior', 'wordlist', 'elective2', 'U5', 'meet a criterion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'rare', 'adj.', '/reə/', '稀有的,罕见的', 'It is one of the rare places where these processes can be seen in real time.', '这是少数能实时观察这些过程的稀有地点之一。', 'A Delicate World', 30, 0, 'senior', 'wordlist', 'elective2', 'U5', 'a rare location', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'prosper', 'v.', '/ˈprɒspə/', '兴旺,繁荣', 'The balanced environment allows many species to live and prosper.', '平衡的环境让众多物种得以生存和繁荣。', 'A Delicate World', 31, 0, 'senior', 'wordlist', 'elective2', 'U5', 'live and prosper', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'apparently', 'adv.', '/əˈpærəntli/', '看来,似乎;据说', 'Apparently, Shennongjia is one of the most complete natural areas in the world.', '看来,神农架是世界上最完整的自然区之一。', 'A Delicate World', 32, 0, 'senior', 'wordlist', 'elective2', 'U5', 'apparently one of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'vast', 'adj.', '/vɑːst/', '巨大的;广大的', 'The vast range in altitude results in great differences in climate.', '海拔上的巨大跨度造成了气候的巨大差异。', 'A Delicate World', 33, 0, 'senior', 'wordlist', 'elective2', 'U5', 'a vast range', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'altitude', 'n.', '/ˈæltɪtjuːd/', '海拔(高度)', 'The region rises to a great altitude of over three thousand metres.', '这一地区上升到三千多米的高海拔。', 'A Delicate World', 34, 0, 'senior', 'wordlist', 'elective2', 'U5', 'high altitude', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'variation', 'n.', '/ˌveəriˈeɪʃ(ə)n/', '差异;变化', 'The wide variation in climate lets many kinds of life thrive.', '气候上的巨大差异让多种生命得以繁衍。', 'A Delicate World', 35, 0, 'senior', 'wordlist', 'elective2', 'U5', 'great variation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'thrive', 'v.', '/θraɪv/', '茁壮成长,兴旺', 'A wide variety of plants and animals thrive in this protected place.', '多种多样的动植物在这片受保护的地方茁壮成长。', 'A Delicate World', 36, 0, 'senior', 'wordlist', 'elective2', 'U5', 'thrive in the wild', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fossil', 'n.', '/ˈfɒs(ə)l/', '化石', 'Some species have survived for millions of years and are seen as living fossils.', '有些物种存活了数百万年,被视为活化石。', 'A Delicate World', 37, 0, 'senior', 'wordlist', 'elective2', 'U5', 'living fossil', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'vertebrate', 'n.', '/ˈvɜːtɪbrɪt/', '脊椎动物', 'Shennongjia supports more than six hundred vertebrate species.', '神农架养育着六百多种脊椎动物。', 'A Delicate World', 38, 0, 'senior', 'wordlist', 'elective2', 'U5', 'vertebrate species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'endangered', 'adj.', '/ɪnˈdeɪndʒəd/', '濒临灭绝的', 'Although endangered elsewhere, the wild bees here are doing well.', '尽管在别处濒危,这里的野蜂却生活得很好。', 'A Delicate World', 39, 0, 'senior', 'wordlist', 'elective2', 'U5', 'endangered species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'elsewhere', 'adv.', '/elsˈweə/', '在别处', 'These bees have died out elsewhere but still thrive in the forest.', '这些蜂在别处已经绝迹,在这片森林里却依然兴旺。', 'A Delicate World', 40, 0, 'senior', 'wordlist', 'elective2', 'U5', 'endangered elsewhere', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'invasion', 'n.', '/ɪnˈveɪʒ(ə)n/', '涌入;入侵', 'The native bees are threatened by the invasion of foreign species.', '本地蜂受到外来物种入侵的威胁。', 'A Delicate World', 41, 0, 'senior', 'wordlist', 'elective2', 'U5', 'the invasion of foreign species', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'coexist', 'v.', '/ˌkəʊɪɡˈzɪst/', '共存,共处', 'The villagers and the wild bees coexist in harmony with nature.', '村民与野蜂和自然和谐共处。', 'A Delicate World', 42, 0, 'senior', 'wordlist', 'elective2', 'U5', 'coexist with nature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'secure', 'adj.', '/sɪˈkjʊə/', '稳固的;安全的', 'By giving the bees a secure home, the villagers collect honey in return.', '村民给蜂提供安全的家园,作为回报采集蜂蜜。', 'A Delicate World', 43, 0, 'senior', 'wordlist', 'elective2', 'U5', 'a secure home', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'beehive', 'n.', '/ˈbiːhaɪv/', '蜂房,蜂箱', 'Every spring the villagers place beehives around their houses.', '每年春天,村民都在屋子周围放置蜂箱。', 'A Delicate World', 44, 0, 'senior', 'wordlist', 'elective2', 'U5', 'place beehives', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'comparison', 'n.', '/kəmˈpærɪs(ə)n/', '比较', 'A simple comparison between the two parks shows how special each one is.', '对两座公园做个简单比较,就能看出各自的独特之处。', 'A Delicate World', 45, 0, 'senior', 'wordlist', 'elective2', 'U5', 'make a comparison', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'visual', 'adj.', '/ˈvɪʒuəl/', '视觉的', 'Both verbal and visual information help keep the audience interested.', '口头信息和视觉信息都有助于让听众保持兴趣。', 'A Delicate World', 46, 0, 'senior', 'wordlist', 'elective2', 'U5', 'visual information', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'session', 'n.', '/ˈseʃ(ə)n/', '一段时间;一节', 'The talk ends with a short question-and-answer session.', '讲座以简短的问答环节结束。', 'A Delicate World', 47, 0, 'senior', 'wordlist', 'elective2', 'U5', 'a question session', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u5.01', '①动词 + it + 形容词 + to do(find/think/feel/consider it hard to…)', 'A2', 11, '外研社版选择性必修第二册 U5 — 当不定式作宾语、后面又跟形容词作宾补时,把不定式后移、用 it 作形式宾语顶在前面:find/think/feel/consider/make it + 形容词 + to do…。it 预指后面的不定式,that/this/them 没有所指。', 1, 'elective2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u5.02', '②动词 + it + 形容词/名词 + that 从句(make it clear that…)', 'A2', 11, '外研社版选择性必修第二册 U5 — 当 that 从句作宾语、后面又跟形容词或名词作宾补时,用 it 作形式宾语:make/find/think/consider it + clear/obvious/a pity + that…。it 预指后面的 that 从句。', 2, 'elective2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u5.03', '③make / consider it + 名词 + to do(consider it an honour to…)', 'A2', 11, '外研社版选择性必修第二册 U5 — 当不定式作宾语、后面跟名词作宾补时,同样用 it 作形式宾语:make/consider/think it + a rule/an honour/a duty + to do…。若宾语只是普通名词、不是不定式或从句,则不用 it,因此能否用 it 取决于后面是否有后移的不定式 / 从句。', 3, 'elective2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The rangers found ____ hard to remove every rabbit from the island.', 'it', 'that', 'this', 'them', 'A', 'find it + 形容词 + to do;it 是形式宾语,真正的宾语是后面的不定式 to remove…;that/this/them 无所指。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Visitors think ____ surprising to see so many penguins in one place.', 'that', 'it', 'this', 'them', 'B', 'think it surprising to do;it 预指不定式 to see…。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Experts felt ____ necessary to release a virus to control the rabbits.', 'that', 'this', 'it', 'them', 'C', 'feel it necessary to do;it 是形式宾语,预指 to release…。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'We consider ____ important to protect the birds'' natural habitat.', 'that', 'this', 'them', 'it', 'D', 'consider it important to do;it 预指后置不定式。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Scientists found ____ difficult to study the animals at such a high altitude.', 'it', 'that', 'this', 'them', 'A', 'find it difficult to do;真正的宾语是 to study…,用 it 顶位。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The team thought ____ wiser to use traps rather than poison at first.', 'that', 'it', 'this', 'them', 'B', 'think it + 形容词 + to do;it 预指不定式。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Tourists find ____ amazing to watch the elephant seals rest on the shore.', 'that', 'this', 'it', 'them', 'C', 'find it amazing to do;it 是形式宾语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The villagers consider ____ rewarding to share their home with wild bees.', 'that', 'this', 'them', 'it', 'D', 'consider it rewarding to do;it 预指 to share…。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Researchers found ____ impossible to save the parakeets in time.', 'it', 'that', 'this', 'them', 'A', 'find it impossible to do;it 顶位,真正的宾语后移。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Many people think ____ unfair to blame only the cats for the disaster.', 'that', 'it', 'this', 'them', 'B', 'think it unfair to do;it 预指不定式。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The guide made ____ easy for us to understand the food chain.', 'that', 'this', 'it', 'them', 'C', 'make it easy (for sb) to do;it 是形式宾语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Conservationists find ____ challenging to keep such a fragile world in balance.', 'that', 'this', 'them', 'it', 'D', 'find it challenging to do;it 预指后置不定式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'We think ____ wonderful to visit a place so wild and natural.', 'it', 'that', 'this', 'them', 'A', 'think it wonderful to do;it 是形式宾语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The crew found ____ tiring to search every corner of the rocky island.', 'that', 'it', 'this', 'them', 'B', 'find it tiring to do;真正的宾语是 to search…。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Officials thought ____ urgent to act before more soil was washed away.', 'that', 'this', 'it', 'them', 'C', 'think it urgent to do;it 预指不定式。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'We find ____ encouraging to see the ecology slowly recover.', 'that', 'this', 'them', 'it', 'D', 'find it encouraging to do;it 是形式宾语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The scientists felt ____ vital to record every change in the habitat.', 'it', 'that', 'this', 'them', 'A', 'feel it vital to do;it 预指后置不定式。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Most people think ____ worthwhile to spend money on conservation.', 'that', 'it', 'this', 'them', 'B', 'think it worthwhile to do;it 是形式宾语。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'The rangers found ____ useful to bring trained dogs onto the island.', 'that', 'this', 'it', 'them', 'C', 'find it useful to do;真正的宾语后移,用 it 顶位。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.01'), 'Everyone found ____ shocking to learn that the parakeets had died out.', 'that', 'this', 'them', 'it', 'D', 'find it shocking to do;it 预指不定式 to learn…。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The incident made ____ clear that the rabbit problem had to be solved.', 'it', 'that', 'this', 'them', 'A', 'make it clear that…;it 是形式宾语,真正的宾语是后面的 that 从句。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'Recent studies have made ____ obvious that human activity harmed the island.', 'that', 'it', 'this', 'them', 'B', 'make it obvious that…;it 预指 that 从句。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The report made ____ plain that the cats were killing the native birds.', 'that', 'this', 'it', 'them', 'C', 'make it plain that…;it 顶位,that 从句后移。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'Scientists consider ____ likely that the rats arrived on the early ships.', 'that', 'this', 'them', 'it', 'D', 'consider it likely that…;it 是形式宾语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'History makes ____ clear that one small change can upset a whole system.', 'it', 'that', 'this', 'them', 'A', 'make it clear that…;it 预指 that 从句。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The new data made ____ evident that the bee population was falling fast.', 'that', 'it', 'this', 'them', 'B', 'make it evident that…;it 是形式宾语。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'We think ____ a pity that so many species have disappeared forever.', 'that', 'this', 'it', 'them', 'C', 'think it a pity that…;it 预指后面的 that 从句,a pity 作宾补。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The guide made ____ clear that visitors must not feed the wild animals.', 'that', 'this', 'them', 'it', 'D', 'make it clear that…;it 是形式宾语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'Experts find ____ worrying that the virus no longer stops the rabbits.', 'it', 'that', 'this', 'them', 'A', 'find it worrying that…;it 预指 that 从句。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The film made ____ obvious that nature can recover if people help.', 'that', 'it', 'this', 'them', 'B', 'make it obvious that…;it 是形式宾语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'Officials made ____ known that the island was at last free of pests.', 'that', 'this', 'it', 'them', 'C', 'make it known that…;it 顶位,that 从句后移。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The story makes ____ clear that humans owe the island a happy ending.', 'that', 'this', 'them', 'it', 'D', 'make it clear that…;it 预指后面的 that 从句。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'Researchers consider ____ certain that warming will change many habitats.', 'it', 'that', 'this', 'them', 'A', 'consider it certain that…;it 是形式宾语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The lecture made ____ plain that biodiversity keeps an ecosystem healthy.', 'that', 'it', 'this', 'them', 'B', 'make it plain that…;it 预指 that 从句。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'We feel ____ a shame that the parakeets were lost so quickly.', 'that', 'this', 'it', 'them', 'C', 'feel it a shame that…;it 是形式宾语,a shame 作宾补。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The teacher made ____ clear that every species has its own role to play.', 'that', 'this', 'them', 'it', 'D', 'make it clear that…;it 预指 that 从句。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'New evidence makes ____ obvious that the rabbits caused the soil erosion.', 'it', 'that', 'this', 'them', 'A', 'make it obvious that…;it 是形式宾语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The committee thought ____ important that local people join the project.', 'that', 'it', 'this', 'them', 'B', 'think it important that…(虚拟语气);it 预指 that 从句。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The signs make ____ clear that this is a protected nature reserve.', 'that', 'this', 'it', 'them', 'C', 'make it clear that…;it 是形式宾语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.02'), 'The success made ____ clear that careful planning can save a species.', 'that', 'this', 'them', 'it', 'D', 'make it clear that…;it 预指后面的 that 从句。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The villagers consider ____ an honour to protect the wild forest bees.', 'it', 'that', 'this', 'them', 'A', 'consider it an honour to do;it 是形式宾语,an honour 作宾补,真正的宾语是 to protect…。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The team made ____ a rule to check every trap each morning.', 'that', 'it', 'this', 'them', 'B', 'make it a rule to do;it 预指后置不定式。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'Scientists consider ____ their duty to study the endangered species.', 'that', 'this', 'it', 'them', 'C', 'consider it one''s duty to do;it 是形式宾语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'We think ____ a mistake to bring new animals onto a small island.', 'that', 'this', 'them', 'it', 'D', 'think it a mistake to do;it 预指不定式。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The rangers made ____ a priority to remove the very last cats.', 'it', 'that', 'this', 'them', 'A', 'make it a priority to do;it 是形式宾语。', 2, 5, 'mcq');
