INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The guide made ____ a point to explain the food chain clearly.', 'that', 'this', 'it', 'them', 'C', 'make it a point to do;it 是形式宾语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'Conservationists consider ____ a challenge to keep the habitat safe.', 'that', 'this', 'them', 'it', 'D', 'consider it a challenge to do;it 预指 to keep…。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The crew made ____ their goal to find every remaining rabbit.', 'it', 'that', 'this', 'them', 'A', 'make it one''s goal to do;it 是形式宾语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'Local people think ____ a joy to live so close to nature.', 'that', 'it', 'this', 'them', 'B', 'think it a joy to do;it 预指后置不定式。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The government made ____ a law to ban hunting in the reserve.', 'that', 'this', 'it', 'them', 'C', 'make it a law to do;it 是形式宾语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'Researchers consider ____ a success to bring the rare species back.', 'that', 'this', 'them', 'it', 'D', 'consider it a success to do;it 预指 to bring…。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'We consider ____ a responsibility to repair the damage we have caused.', 'it', 'that', 'this', 'them', 'A', 'consider it a responsibility to do;it 是形式宾语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The school made ____ a tradition to plant young trees every spring.', 'that', 'it', 'this', 'them', 'B', 'make it a tradition to do;it 预指后置不定式。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'Visitors think ____ a treat to watch the penguins return each year.', 'that', 'this', 'it', 'them', 'C', 'think it a treat to do;it 是形式宾语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The experts made ____ a habit to record the animals every week.', 'that', 'this', 'them', 'it', 'D', 'make it a habit to do;it 预指 to record…。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The villagers consider ____ a blessing to share the forest with the bees.', 'it', 'that', 'this', 'them', 'A', 'consider it a blessing to do;it 是形式宾语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The team made ____ their mission to give the island a happy ending.', 'that', 'it', 'this', 'them', 'B', 'make it one''s mission to do;it 预指后置不定式。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'We think ____ a shame to waste such a delicate, beautiful world.', 'that', 'this', 'it', 'them', 'C', 'think it a shame to do;it 是形式宾语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U5' AND code='fe2u5.03'), 'The country made ____ a goal to protect its precious natural heritage.', 'that', 'this', 'them', 'it', 'D', 'make it a goal to do;it 预指后面的不定式 to protect…。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Chaos on Macquarie Island', 'Macquarie Island lies in the cold ocean halfway between Australia and Antarctica. With its green grass and bare rock, it has a wild and natural beauty, and no visitor would think it surprising that the island became a World Heritage site. Sadly, its more recent history is a tragic one. When humans arrived in 1810, their ships secretly carried rats and mice, which quickly began eating the seabirds'' eggs. Cats were then brought to control the rats, but the cats soon developed an appetite for the native birds as well. Later, rabbits were introduced as food for people. They multiplied rapidly, ate the vegetation and dug holes that caused serious soil erosion. With so many rabbits to feed on, the number of cats also grew, and even more birds were hunted. In the end, the parakeets that were once native to the island died out completely. The story shows how one small change, made by people, can throw a whole delicate world into chaos.', '说明·入侵物种如何破坏脆弱生态', 164, '[{"q":"Why would visitors not be surprised that the island is protected?","answer":"A","options":["Because of its wild, natural beauty.","Because it is close to a big city.","Because no animals live there.","Because it is easy to reach."],"explanation":"原文 ''wild and natural beauty… would think it surprising'' 的转述。"},{"q":"What did the cats end up doing on the island?","answer":"B","options":["They left the island at once.","They began hunting the native birds.","They protected the seabirds'' eggs.","They ate only the rabbits."],"explanation":"原文 ''developed an appetite for the native birds'' 的转述。"},{"q":"What does the story mainly show?","answer":"A","options":["That human actions can upset a whole ecosystem.","That islands are good places for pets.","That rabbits make the best food.","That cats and birds are natural friends."],"explanation":"末句 ''one small change… can throw a whole delicate world into chaos'' 的转述。"}]'::jsonb, '[{"word":"erosion","cn":"侵蚀"},{"word":"vegetation","cn":"草木"},{"word":"chaos","cn":"混乱"}]'::jsonb, 2, 'elective2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Why Shennongjia Matters', 'Shennongjia, in central China, was added to the World Heritage List in 2016. It earned this status because it meets two important standards. First, it offers a naturally balanced environment where many different species can live and prosper. The land rises from about four hundred metres to over three thousand metres, and this vast range in altitude creates great variation in climate. As a result, a wide variety of plants and animals are able to thrive, and some of them have survived for millions of years. Second, Shennongjia has incredible biodiversity. More than three thousand plant species and over six hundred vertebrate species have been recorded there, including the rare golden snub-nosed monkey. To protect these animals, scientists brave heavy snow in winter to bring them food. Thanks to such hard work, the monkey''s numbers have doubled since the 1980s. Local people also take what they need from nature without causing damage, living in harmony with the world around them.', '说明·世界遗产地的生物多样性', 160, '[{"q":"Why was Shennongjia added to the Heritage List?","answer":"B","options":["Because it is the highest place in China.","Because it meets two key standards.","Because no one lives near it.","Because it has the most tourists."],"explanation":"原文 ''meets two important standards'' 的转述。"},{"q":"What makes so many kinds of life able to thrive there?","answer":"C","options":["The lack of any rain.","The help of foreign animals.","The huge range in altitude and climate.","The absence of all winter."],"explanation":"原文 ''vast range in altitude creates great variation in climate… able to thrive'' 的转述。"},{"q":"How do scientists help the monkeys in winter?","answer":"D","options":["They move the monkeys to cities.","They build large warm houses.","They feed them only in summer.","They carry food to them through heavy snow."],"explanation":"原文 ''brave heavy snow in winter to bring them food'' 的转述。"}]'::jsonb, '[{"word":"altitude","cn":"海拔"},{"word":"thrive","cn":"茁壮成长"},{"word":"vertebrate","cn":"脊椎动物"}]'::jsonb, 2, 'elective2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Links in the Food Chain', 'Every healthy ecosystem depends on a chain of living things that pass energy from one to another. At the bottom are the producers, such as green plants. They take in water and nutrients from the soil and make their own food using light from the sun. Next come the primary consumers, like insects, which feed on these green plants. They in turn become food for secondary consumers, such as small birds and mammals, that prey on the primary consumers. When plants and animals die, decomposers like fungi and bacteria break down their remains into nutrients. These nutrients are released back into the soil, where the producers can use them once more. In this way nothing is wasted, and the cycle begins again. If even one link in this chain is removed, the whole system can fall out of balance. That is why scientists say that every species, however small it may be, has its own part to play.', '说明·食物链各角色与生态平衡', 158, '[{"q":"What do producers use to make their own food?","answer":"A","options":["Sunlight, along with water and nutrients.","Only other animals.","Dead leaves alone.","Nothing at all."],"explanation":"原文 ''take in water and nutrients… using light from the sun'' 的转述。"},{"q":"What is the job of the decomposers?","answer":"B","options":["To eat the green plants first.","To turn dead remains back into nutrients.","To hunt the secondary consumers.","To make food from sunlight."],"explanation":"原文 ''break down their remains into nutrients'' 的转述。"},{"q":"What happens if one link in the chain disappears?","answer":"C","options":["The plants grow much faster.","Nothing changes at all.","The whole system may lose its balance.","The sun stops giving energy."],"explanation":"原文 ''one link… removed, the whole system can fall out of balance'' 的转述。"}]'::jsonb, '[{"word":"nutrient","cn":"养分"},{"word":"ecology","cn":"生态"}]'::jsonb, 2, 'elective2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Cute but Dangerous Pet', 'The red-eared slider is a small freshwater turtle that comes from the southern United States and northern Mexico. Because it looks cute, many people once thought that it would make a perfect pet. Over the years, however, more and more owners have let their turtles escape or have set them free, believing that this does no harm. Experts now warn that releasing these turtles into the wild is far from harmless. In a new place the slider has no natural enemies, so it quickly multiplies and competes with local species for food and space. Some native animals have become endangered as a result. The turtle has now spread to lakes and rivers far from its original home, where it upsets the local balance of nature. Experts say that owners should keep their pets in an enclosed area, and that anyone who can no longer care for a turtle should take it to an animal shelter rather than abandon it in the wild.', '说明·外来宠物巴西龟的威胁', 162, '[{"q":"Why did people once want this turtle as a pet?","answer":"D","options":["Because it was very rare.","Because it could not move.","Because it ate harmful insects.","Because of its cute appearance."],"explanation":"原文 ''Because it looks cute… a perfect pet'' 的转述。"},{"q":"Why is releasing the slider into the wild dangerous?","answer":"A","options":["It breeds fast and crowds out native species.","It dies within a few days.","It only eats plants people grow.","It cannot live in lakes or rivers."],"explanation":"原文 ''quickly multiplies and competes with local species… endangered'' 的转述。"},{"q":"What do experts advise turtle owners to do?","answer":"B","options":["Set the turtles free in any river.","Keep them enclosed or hand them to a shelter.","Sell the turtles to other countries.","Let the turtles find new homes alone."],"explanation":"原文 ''keep their pets in an enclosed area… take it to an animal shelter'' 的转述。"}]'::jsonb, '[{"word":"endangered","cn":"濒危的"},{"word":"multiply","cn":"大量繁殖"}]'::jsonb, 2, 'elective2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Treasure of Fanjing Mountain', 'Fanjing Mountain, in Guizhou Province, is one of China''s natural treasures. In recent years it was added to the World Heritage List, bringing the total number of such sites in China to fifty-three. The main reason for its inclusion is its remarkable biological diversity. About fifty endangered plant and animal species are found within its protected area, and some of them live nowhere else on Earth. As one of the first national nature reserves in the country, Fanjing Mountain stands as one of China''s greatest achievements in protecting the environment. It is also famous for its breathtaking scenery, with green peaks that often rise above a sea of cloud, making it a popular summer resort. Yet the mountain is far more than a beautiful view. By keeping its forests safe, China protects a home for rare creatures and shows the world that economic growth and a healthy environment can stand side by side.', '说明·梵净山自然遗产与绿色发展', 153, '[{"q":"Why was Fanjing Mountain put on the Heritage List?","answer":"C","options":["Because it is the tallest mountain in China.","Because it has the largest city nearby.","Mainly because of its rich biological variety.","Because no plants grow on it."],"explanation":"原文 ''main reason for its inclusion is its remarkable biological diversity'' 的转述。"},{"q":"What is special about some of the species there?","answer":"D","options":["They are kept only in zoos.","They were brought from abroad.","They have all died out.","They are found nowhere else in the world."],"explanation":"原文 ''some of them live nowhere else on Earth'' 的转述。"},{"q":"What message does the mountain send, according to the text?","answer":"A","options":["Economic progress and nature can move forward together.","Tourists should stay away from nature.","Old forests should be cut down.","Only money really matters in the end."],"explanation":"末句 ''economic growth and a healthy environment can stand side by side'' 的转述。"}]'::jsonb, '[{"word":"rare","cn":"稀有的"},{"word":"conservation","cn":"保护"}]'::jsonb, 2, 'elective2', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'From Desert to Forest', 'Sixty years ago, Saihanba in northern China was a cold, empty wasteland where strong winds blew sand across the bare ground. Few people believed that anything could grow there. Then a group of workers arrived with a bold dream: to turn the desert into a forest. Year after year, in freezing weather, they planted young trees by hand, and slowly the green began to spread. Many of the first trees died, but the workers refused to give up. Today Saihanba is the largest planted forest in the world. Its millions of trees hold the soil in place, clean the air, and store huge amounts of water for the cities to the south. Wild animals that had long disappeared have returned to live among the trees. The story of Saihanba shows that, with patience and hard work, people can not only stop damaging nature but also help a ruined land come back to life.', '记叙·塞罕坝荒原变林海', 153, '[{"q":"What was Saihanba like sixty years ago?","answer":"B","options":["A busy city full of people.","A cold, sandy wasteland with almost no plants.","A green forest full of animals.","A large lake beside the sea."],"explanation":"原文 ''cold, empty wasteland where strong winds blew sand'' 的转述。"},{"q":"How did the workers create the forest?","answer":"C","options":["By buying trees from other countries.","By waiting for the rain to do the work.","Through years of planting trees by hand.","By moving a forest from the south."],"explanation":"原文 ''Year after year… they planted young trees by hand'' 的转述。"},{"q":"What does the story of Saihanba mainly show?","answer":"D","options":["That deserts can never change.","That trees are not worth planting.","That nature looks after itself alone.","That damaged land can be brought back to life."],"explanation":"末句 ''help a ruined land come back to life'' 的转述。"}]'::jsonb, '[{"word":"vast","cn":"广大的"},{"word":"thrive","cn":"茁壮成长"}]'::jsonb, 2, 'elective2', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U5', 'Why Bees Matter', 'Bees may be small, but they play a (1)____ part in keeping our world alive. As they move from flower to flower, they carry pollen and help plants to produce fruit and (2)____. In fact, a large share of the food we eat depends on this quiet work. Sadly, in recent years the bee (3)____ has been falling fast in many countries. Scientists believe that a (4)____ of causes, including the loss of wild flowers and the use of chemicals, is to (5)____. If bees were to (6)____ out completely, other insects could not easily take their place, because so many kinds of crops (7)____ on them. The good news is that ordinary people can (8)____. By planting flowers, avoiding harmful sprays and protecting wild (9)____, we can give bees a safer home. Every small action helps to keep this delicate (10)____ in balance.', 144, 2, '[{"q":"1","answer":"A","options":["important","silent","heavy","cheap"],"explanation":"play an important part 起重要作用。"},{"q":"2","answer":"B","options":["stones","seeds","clouds","coins"],"explanation":"produce fruit and seeds 结果实和种子。"},{"q":"3","answer":"C","options":["holiday","machine","population","building"],"explanation":"the bee population 蜜蜂数量。"},{"q":"4","answer":"D","options":["holiday","picture","window","combination"],"explanation":"a combination of causes 多种原因的结合。"},{"q":"5","answer":"A","options":["blame","sell","paint","drive"],"explanation":"be to blame 应负责任。"},{"q":"6","answer":"B","options":["sing","die","build","paint"],"explanation":"die out 灭绝。"},{"q":"7","answer":"C","options":["sit","jump","depend","sleep"],"explanation":"depend on 依赖。"},{"q":"8","answer":"D","options":["sleep","shout","hide","help"],"explanation":"people can help 人们能帮上忙。"},{"q":"9","answer":"A","options":["habitats","tickets","songs","prices"],"explanation":"protecting wild habitats 保护野生栖息地。"},{"q":"10","answer":"B","options":["market","world","machine","song"],"explanation":"this delicate world 这个脆弱的世界。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U5', 'A Ranger''s Quiet Work', 'My name is Sam, and I work as a wildlife ranger on a small, windy (1)____ far out at sea. Long ago, sailors accidentally brought rats and rabbits here, and these animals soon (2)____ in number until they were everywhere. They ate the eggs of the seabirds and dug holes that damaged the (3)____. My job is to help (4)____ the last of these unwanted visitors so that the native birds can be (5)____ once more. It is slow and tiring work. Each morning I check every (6)____ to see what we have caught, and I walk for hours across the rocky ground with my trained (7)____, who can find hidden animals without harming the birds. We have already made huge (8)____, and the seabirds are slowly coming back. People once caused this (9)____ without meaning to, so I feel that we (10)____ it to the island to put things right.', 151, 2, '[{"q":"1","answer":"C","options":["kitchen","library","island","market"],"explanation":"a windy island 一座多风的岛。"},{"q":"2","answer":"D","options":["sang","painted","slept","increased"],"explanation":"increased in number 数量增多。"},{"q":"3","answer":"A","options":["soil","music","paper","glass"],"explanation":"damaged the soil 破坏了土壤。"},{"q":"4","answer":"B","options":["paint","remove","borrow","sing"],"explanation":"help remove 帮助清除。"},{"q":"5","answer":"C","options":["angry","cheap","safe","late"],"explanation":"be safe once more 重新安全。"},{"q":"6","answer":"D","options":["song","price","window","trap"],"explanation":"check every trap 检查每个陷阱。"},{"q":"7","answer":"A","options":["dogs","books","cars","clouds"],"explanation":"trained dogs 受过训练的狗。"},{"q":"8","answer":"B","options":["noise","progress","rubbish","weather"],"explanation":"made huge progress 取得巨大进展。"},{"q":"9","answer":"C","options":["holiday","picture","chaos","song"],"explanation":"caused this chaos 造成了这场混乱。"},{"q":"10","answer":"D","options":["sell","lose","paint","owe"],"explanation":"owe it to the island 对这座岛负有义务。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U5', 'Saving the Golden Monkey', 'High in the mountains of central China lives the rare golden snub-nosed (1)____, an animal found in very few places on Earth. Life there is hard, especially in winter, when heavy (2)____ covers the ground and food becomes difficult to find. To help the animals (3)____ through the coldest months, scientists climb the freezing slopes carrying food on their backs. Without this (4)____, many of the weaker animals might not last until spring. Year after year, the team records how many monkeys (5)____ in each group and watches how the young ones grow. Thanks to their patient (6)____, the number of monkeys has slowly (7)____, and today there are far more than there were in the 1980s. The story is a (8)____ reminder that protecting a single species often takes many years of quiet effort. By keeping their mountain home (9)____, we make sure that these gentle animals can (10)____ for years to come.', 154, 2, '[{"q":"1","answer":"A","options":["monkey","market","machine","mirror"],"explanation":"golden snub-nosed monkey 金丝猴。"},{"q":"2","answer":"B","options":["sand","snow","smoke","paper"],"explanation":"heavy snow 大雪。"},{"q":"3","answer":"C","options":["shout","borrow","survive","paint"],"explanation":"survive through winter 熬过冬天。"},{"q":"4","answer":"D","options":["noise","price","holiday","help"],"explanation":"without this help 没有这份帮助。"},{"q":"5","answer":"A","options":["live","sell","paint","shout"],"explanation":"how many monkeys live 有多少猴子生活。"},{"q":"6","answer":"B","options":["noise","work","price","weather"],"explanation":"their patient work 他们耐心的工作。"},{"q":"7","answer":"C","options":["fallen","disappeared","risen","stopped"],"explanation":"has slowly risen;下文''far more than 1980s''说明在增多。"},{"q":"8","answer":"D","options":["cheap","late","empty","clear"],"explanation":"a clear reminder 一个清楚的提醒。"},{"q":"9","answer":"A","options":["safe","angry","busy","rich"],"explanation":"keep their home safe 保持家园安全。"},{"q":"10","answer":"B","options":["fail","thrive","vanish","quit"],"explanation":"can thrive 能茁壮成长。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U5', 'The Lost Sea', 'The Aral Sea was once one of the largest lakes in the world, full of fish and surrounded by busy fishing (1)____. Then, many years ago, people began taking huge amounts of (2)____ from the rivers that fed it, in order to grow crops in the desert. Little by little, the great lake began to (3)____. As the water disappeared, the fish died and the boats were left lying on dry (4)____. The fishing towns lost their main source of (5)____, and many families had to move (6)____. Dust and salt from the empty lake bed blew across the land, making people (7)____. The story of the Aral Sea is a sad (8)____ of how quickly nature can change when it is not treated with care. In recent years, however, careful (9)____ has brought part of the northern lake back to life, giving local people new (10)____ that the damage can slowly be repaired.', 154, 2, '[{"q":"1","answer":"C","options":["clouds","songs","towns","clocks"],"explanation":"fishing towns 渔镇。"},{"q":"2","answer":"D","options":["music","sand","paper","water"],"explanation":"taking water from the rivers 从河里取水。"},{"q":"3","answer":"A","options":["shrink","sing","shine","float"],"explanation":"began to shrink 开始缩小。"},{"q":"4","answer":"B","options":["music","land","glass","paper"],"explanation":"on dry land 在干涸的陆地上。"},{"q":"5","answer":"C","options":["weather","noise","income","colour"],"explanation":"source of income 收入来源。"},{"q":"6","answer":"D","options":["asleep","awake","aside","away"],"explanation":"move away 搬走。"},{"q":"7","answer":"A","options":["ill","rich","proud","glad"],"explanation":"making people ill 使人生病。"},{"q":"8","answer":"B","options":["holiday","lesson","machine","garden"],"explanation":"a sad lesson 一个惨痛的教训。"},{"q":"9","answer":"C","options":["weather","traffic","conservation","fashion"],"explanation":"careful conservation 细心的保护。"},{"q":"10","answer":"D","options":["fear","noise","dust","hope"],"explanation":"new hope 新的希望;下文''can be repaired''。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U5', 'The Rainforests of the Sea', 'Coral reefs are sometimes called the rainforests of the (1)____, because so many kinds of living things make their home among them. Although reefs cover only a tiny part of the ocean floor, they support an enormous (2)____ of fish and other sea creatures. Sadly, reefs around the world are now in serious (3)____. As the sea grows warmer, the coral loses its bright colours and slowly (4)____. Pollution and careless fishing make the problem even (5)____. When a reef dies, the many animals that (6)____ on it for food and shelter are forced to leave or die. Scientists are working hard to (7)____ these underwater worlds before it is too late. In some places, people grow new coral and plant it on damaged reefs, giving them a chance to (8)____ again. Protecting the reefs matters to everyone, for a healthy ocean helps to keep the whole (9)____ in balance. Each of us can (10)____ by keeping the sea clean.', 160, 2, '[{"q":"1","answer":"A","options":["sea","sky","city","desert"],"explanation":"the rainforests of the sea 海洋中的雨林。"},{"q":"2","answer":"B","options":["silence","variety","holiday","machine"],"explanation":"an enormous variety of fish 大量种类的鱼。"},{"q":"3","answer":"C","options":["colour","fashion","danger","weather"],"explanation":"in serious danger 处于严重危险中。"},{"q":"4","answer":"D","options":["sings","shines","floats","dies"],"explanation":"slowly dies 慢慢死去。"},{"q":"5","answer":"A","options":["worse","richer","louder","colder"],"explanation":"make the problem even worse 让问题更糟。"},{"q":"6","answer":"B","options":["sit","depend","jump","sleep"],"explanation":"depend on it 依赖珊瑚礁。"},{"q":"7","answer":"C","options":["sell","paint","save","forget"],"explanation":"save these worlds 拯救这些世界。"},{"q":"8","answer":"D","options":["fail","vanish","sink","grow"],"explanation":"a chance to grow again 再次生长的机会。"},{"q":"9","answer":"A","options":["world","market","machine","song"],"explanation":"keep the whole world in balance 保持整个世界的平衡。"},{"q":"10","answer":"B","options":["shout","help","hide","sleep"],"explanation":"each of us can help 我们每个人都能帮忙。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U5', 'The Wetland Near My Home', 'Near my home there is a small (1)____ where many wild birds come to rest and feed. When I was young, the water was dirty and full of rubbish, and few birds could be (2)____ there. A few years ago, our town decided to (3)____ the area and turn it into a nature park. Workers cleared away the rubbish, planted reeds along the banks, and asked people not to (4)____ the wildlife. Slowly the water became (5)____ again, and the birds began to return. Last spring I (6)____ more than twenty different kinds in a single morning. Helping with the clean-up has changed the (7)____ I see nature. I used to think that one person could not (8)____ much, but now I know that small actions, added together, can make a real (9)____. I feel proud that our town chose to protect this quiet corner of the (10)____ world.', 149, 2, '[{"q":"1","answer":"C","options":["kitchen","market","wetland","library"],"explanation":"a small wetland 一小片湿地。"},{"q":"2","answer":"D","options":["sold","sung","thrown","seen"],"explanation":"could be seen 能被看到。"},{"q":"3","answer":"A","options":["clean","sell","paint","borrow"],"explanation":"clean the area 清理这片区域。"},{"q":"4","answer":"B","options":["paint","disturb","borrow","sell"],"explanation":"not to disturb the wildlife 不要打扰野生动物。"},{"q":"5","answer":"C","options":["angry","late","clear","rich"],"explanation":"the water became clear 水变清了。"},{"q":"6","answer":"D","options":["sold","lost","threw","counted"],"explanation":"I counted more than twenty kinds 我数到二十多种。"},{"q":"7","answer":"A","options":["way","price","noise","weather"],"explanation":"changed the way I see nature 改变了我看自然的方式。"},{"q":"8","answer":"B","options":["sell","change","paint","borrow"],"explanation":"could not change much 改变不了多少。"},{"q":"9","answer":"C","options":["holiday","machine","difference","garden"],"explanation":"make a real difference 带来真正的改变。"},{"q":"10","answer":"D","options":["angry","cheap","busy","natural"],"explanation":"the natural world 自然世界。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·对话 Joining the Nature Club', '外研社版选择性必修第二册 U5 · dialogue', 3, 'Mia: Leo, the nature club is looking for volunteers this weekend. Want to join?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·短文 Saving the Wild Tiger', '外研社版选择性必修第二册 U5 · passage', 2, 'The wild tiger is one of the most beautiful animals on Earth, but it is also in great danger.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·对话 A Visit to the Reserve', '外研社版选择性必修第二册 U5 · dialogue', 3, 'Visitor: Excuse me, is it true that this island once had almost no birds left?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·短文 Trees in the City', '外研社版选择性必修第二册 U5 · passage', 2, 'Trees do far more for a city than make it look pretty.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·对话 Cutting Down on Plastic', '外研社版选择性必修第二册 U5 · dialogue', 3, 'Anna: I read that millions of sea animals die each year because of plastic. It''s awful.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U5 听力·短文 A Tip for Helping Birds', '外研社版选择性必修第二册 U5 · passage', 2, 'Here is a simple way to help the wild birds near your home.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Describe How a Place Has Changed(用形式宾语 it 描述一个地方的变化)', 'How Our Wetland Came Back to Life', '假设你是李华,你家附近曾经荒废的湿地经过保护重新焕发生机。请用英语写一篇约80词的短文,内容包括:① 这个地方过去是什么样子;② 人们做了什么来改变它;③ 现在的样子以及你的感受。要求:至少使用一处形式宾语 it 结构(如 find/make/think it + 形容词/名词 + to do / that 从句),句子地道、紧扣主题。', 'Suppose you are Li Hua. A once-ruined wetland near your home has come back to life after people worked to protect it. Write a short passage (about 80 words) including: 1) what the place used to be like; 2) what people did to change it; 3) what it is like now and how you feel. Use the formal object ''it'' at least once (e.g. find/make/think it + adj./n. + to do / that…).', '["过去的样子(The wetland used to be… / Years ago it was…)","人们的行动(People made it a goal to clean… / We found it necessary to…)","现在的变化与感受(Now it is clear that… / I think it wonderful to…)","至少一处形式宾语 it,句句围绕主题"]'::jsonb, 70, 100, 'Years ago, the wetland near my home was a sad sight. The water was dirty, and people found it hard to spot a single bird there. Then our town made it a goal to bring the place back to life. Workers cleared the rubbish, planted reeds and asked everyone not to disturb the wildlife. Slowly the water became clear again. Now it is clear that nature can recover when we care. I think it wonderful to watch the birds return each spring.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["People found it hard to spot a single bird there.","Our town made it a goal to bring the place back to life.","Now it is clear that nature can recover when we care.","I think it wonderful to watch the birds return each spring."]'::jsonb, '[{"wrong":"We found hard to clean the lake.","correct":"We found it hard to clean the lake.","note":"不定式作宾语后移、又有形容词宾补时,必须用形式宾语 it 顶位。"},{"wrong":"The town made clear that it cared about nature.","correct":"The town made it clear that it cared about nature.","note":"that 从句作宾语、后跟形容词宾补时,用 it 作形式宾语。"},{"wrong":"I think wonderful to watch the birds.","correct":"I think it wonderful to watch the birds.","note":"think it + 形容词 + to do,不能漏掉 it。"}]'::jsonb, '【描述地方变化结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U5', '{"title":"形式宾语 it(find / make / think it + adj./n. + to do / that…)速查","intro":"当不定式或 that 从句作宾语、后面又跟形容词或名词作宾语补足语时,把真正的宾语后移,用 it 作形式宾语顶在前面。判断口诀:动词后先填 it,真正的宾语(to do / that…)躲在补足语后面。","table":{"headers":["结构","例句 / 说明"],"rows":[["find/think/feel it + 形容词 + to do","We found it hard to remove the rabbits.(真宾语=to remove…)"],["make/find/think it + 形容词 + that 从句","The incident made it clear that the problem had to be solved."],["consider/make it + 名词 + to do","They consider it an honour to protect the bees.(名词作宾补)"],["常见动词","find / make / think / consider / feel + it + 补足语 + 真宾语"]]},"specialRules":[{"rule":"只有当宾语是‘后移的不定式 / that 从句’时才用 it;若宾语是普通名词则不用","mark":"find it hard to do √ / find the book hard(无 it)"},{"rule":"补足语可以是形容词(clear, hard, necessary)也可以是名词(a rule, an honour, a pity)","mark":"make it a rule to… / think it a pity that…"},{"rule":"it 只是占位,本身无词义,不可换成 that / this / them","mark":"make it clear that… √ / make that clear that… ×"},{"rule":"think it important that… 后的从句常用虚拟语气(should + 动词原形,should 可省)","mark":"think it important that everyone (should) join"}],"why":["英语习惯把太长的不定式或从句放到句末,以免句子‘头重脚轻’;于是先用 it 顶住宾语的位置,真正的宾语后置,读起来更顺、更地道。"],"gaokaoPoints":["形式宾语 it 与形式主语 it 的区别:形式宾语出现在‘动词+it+补足语+真宾语’里(make it clear that…)。","语法填空 / 改错高频:漏掉 it 是典型错误(We found ___ hard to…)。"],"examVsReal":[{"exam":"I find it difficult to finish the task.(考试/书面)","real":"This task is really hard to finish.","note":"考试爱考形式宾语;口语里常直接换个说法把形容词放前面"},{"exam":"They made it clear that smoking was banned.(考试)","real":"They were clear: no smoking.","note":"真实英语口语可用更短、更直接的表达,但书面写作仍用 make it clear that…"}]}'::jsonb, 'fltrp');
